 	extensionUri: vscode.Uri,
 	webview: vscode.Webview,
 ): string {
 	const distUri = vscode.Uri.joinPath(extensionUri, "webview-ui", "dist");
 	const scriptUri = webview.asWebviewUri(
 		vscode.Uri.joinPath(distUri, "assets", "settings.js"),
 	);
