 48		resolveWebviewView(webviewView: vscode.WebviewView): void {
 49			this.view = webviewView;
 50			webviewView.webview.options = {
 51				enableScripts: true,
 52				localResourceRoots: [
 53					vscode.Uri.joinPath(this.extensionUri, "webview-ui", "dist"),
 54				],
 55			};
 56			webviewView.webview.html = buildSettingsHtml(
 57				this.extensionUri,
 58				webviewView.webview,
 59			);
 60			webviewView.webview.onDidReceiveMessage((msg: SettingsMessage) => {
 61				void this.handleMessage(msg);
 62			});
 63		}
 64	
 65		private async handleMessage(msg: SettingsMessage): Promise<void> {
 66			try {
 67				switch (msg.command) {
 68					case "settings:get":
 69					case "settings:refresh":
 70						if (msg.command === "settings:refresh") this.onConfigSaved();
 71						await this.sendData();
 72						break;
 73					case "settings:setBundledResource":
 74						await this.setBundledResource(msg.id, msg.enabled);
 75						break;
 76					case "settings:openFile":
 77						await this.openFile(msg.file);
 78						break;
 79					case "settings:openSessions":
 80						await vscode.commands.executeCommand("codepi.openSessionsTab");
 81						break;
 82				}
 83			} catch (err) {
 84				this.post({
 85					command: "settings:error",
 86					message: err instanceof Error ? err.message : String(err),
 87				});
 88			}
 89		}
 90	
 91		private post(msg: SettingsReply): void {
 92			this.view?.webview.postMessage(msg);
 93		}
 94	
 95		private async sendData(): Promise<void> {
 96			const settingsPath = getSettingsPathForAgent(this.agentDir);
 97			const settings = readJsonFile<Record<string, unknown>>(settingsPath) ?? {};
 98			const sdk = await getSdk();
 99			const cwd =
100				vscode.workspace.workspaceFolders?.[0]?.uri.fsPath ?? this.agentDir;
101			const settingsManager = sdk.SettingsManager.create(cwd, this.agentDir);
102			const packageManager = new sdk.DefaultPackageManager({
103				cwd,
104				agentDir: this.agentDir,
105				settingsManager,
106			});
107			const packages: PackageStatusEntry[] = packageManager
108				.listConfiguredPackages()
109				.map((entry) => ({
110					source: entry.source,
111					scope: entry.scope,
112					installed: entry.installedPath !== undefined,
113				}));
114			const data = buildDashboardData(
115				this.agentDir,
116				this.sessionDir,
117				settings,
118				packages,
119				getDashboardFileStatus(this.agentDir),
120			);
121			this.post({ command: "settings:data", data });
122		}
123	
124		private async setBundledResource(
125			id: DashboardData["bundledResources"][number]["id"],
126			enabled: boolean,
127		): Promise<void> {
128			const settingsPath = getSettingsPathForAgent(this.agentDir);
129			if (!isBundledResourceId(id)) {
130				throw new Error(`Unknown bundled resource: ${id}`);
131			}
132			const settings = readJsonFile<Record<string, unknown>>(settingsPath) ?? {};
133			const current = readBundledResourceConfig(settings);
134			const next: BundledResourceConfig = {
135				bundledExtensions: { ...current.bundledExtensions },
136				bundledThemes: { ...current.bundledThemes },
137			};
138			if (id === "nebula-pulse") next.bundledThemes["nebula-pulse"] = enabled;
139			else next.bundledExtensions[id] = enabled;
140			updateBundledResourceConfig(settingsPath, next);
141			this.onConfigSaved();
142			this.post({ command: "settings:saved", ok: true, resource: id });
143			await this.sendData();
144		}
145	
146		private async openFile(file: "settings" | "models" | "auth"): Promise<void> {
147			const filePath = ensurePiJsonFileInDir(this.agentDir, file);
148			const document = await vscode.workspace.openTextDocument(
149				vscode.Uri.file(filePath),
150			);
151			await vscode.window.showTextDocument(document, { preview: false });
152			this.post({ command: "settings:opened", file, path: filePath });
153		}
154	}
155	
156	function isBundledResourceId(
157		id: string,
158	): id is DashboardData["bundledResources"][number]["id"] {
159		return (
160			id === "custom-footer" || id === "filechanges" || id === "nebula-pulse"
161		);
162	}
163	
164	function getSettingsPathForAgent(agentDir: string): string {
165		return join(agentDir, "settings.json");
166	}
167	
168	function buildSettingsHtml(
169		extensionUri: vscode.Uri,
170		webview: vscode.Webview,
171	): string {
172		const distUri = vscode.Uri.joinPath(extensionUri, "webview-ui", "dist");
173		const scriptUri = webview.asWebviewUri(
174			vscode.Uri.joinPath(distUri, "assets", "settings.js"),
175		);
176		const styleUri = webview.asWebviewUri(
177			vscode.Uri.joinPath(distUri, "assets", "index.css"),
178		);
179		const nonce = getNonce();
180		return /* html */ `<!DOCTYPE html>
181	<html lang="en">
182	<head>
183	  <meta charset="UTF-8" />
184	  <meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src ${webview.cspSource} 'unsafe-inline'; script-src ${webview.cspSource} 'nonce-${nonce}';" />
185	  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
186	  <link rel="stylesheet" crossorigin href="${styleUri}" />
187	  <title>CodePi Settings</title>
188	</head>
189	<body>
190	  <div id="root"></div>
  1	import { existsSync, statSync } from "node:fs";
  2	import { join } from "node:path";
  3	import { BUNDLED_RESOURCES, getEnabledBundledResources } from "./pi-store";
  4	import type {
  5		DashboardData,
  6		PackageStatusEntry,
  7	} from "./shared/settings-protocol";
  8	
  9	export interface DashboardFileStatus {
 10		settings: boolean;
 11		models: boolean;
 12		auth: boolean;
 13	}
 14	
 15	/**
 16	 * Return only filesystem metadata for the Pi JSON files.
 17	 * In particular, auth.json is never read or parsed here.
 18	 */
 19	export function getDashboardFileStatus(agentDir: string): DashboardFileStatus {
 20		const fileExists = (name: string): boolean => {
 21			const filePath = join(agentDir, name);
 22			try {
 23				return existsSync(filePath) && statSync(filePath).isFile();
 24			} catch {
 25				return false;
 26			}
 27		};
 28		return {
 29			settings: fileExists("settings.json"),
 30			models: fileExists("models.json"),
 31			auth: fileExists("auth.json"),
 32		};
 33	}
 34	
 35	/** Build credential-free dashboard data for the settings webview. */
 36	export function buildDashboardData(
 37		agentDir: string,
 38		sessionDir: string,
 39		settings: unknown,
 40		packages: PackageStatusEntry[],
 41		files: DashboardFileStatus = { settings: false, models: false, auth: false },
 42	): DashboardData {
 43		const enabledIds = new Set(
 44			getEnabledBundledResources(settings).map((resource) => resource.id),
 45		);
 46		return {
 47			agentDir,
 48			sessionDir,
 49			bundledResources: BUNDLED_RESOURCES.map((resource) => ({
 50				...resource,
 51				enabled: enabledIds.has(resource.id),
 52			})),
 53			packages: {
 54				configured: packages.length,
 55				installed: packages.filter((entry) => entry.installed).length,
 56				missing: packages.filter((entry) => !entry.installed).length,
 57				entries: packages,
 58			},
 59			files: {
 60				settings: {
 61					path: join(agentDir, "settings.json"),
 62					exists: files.settings,
 63				},
 64				models: { path: join(agentDir, "models.json"), exists: files.models },
 65				auth: { path: join(agentDir, "auth.json"), exists: files.auth },
 66			},
 67		};
 68	}
