  1	import React, { useCallback, useEffect, useState } from "react";
  2	import type {
  3		BundledResourceRow,
  4		DashboardData,
  5		SettingsMessage,
  6		SettingsReply,
  7	} from "./types";
  8	
  9	const vscode = acquireVsCodeApi();
 10	
 11	function post(message: SettingsMessage): void {
 12		vscode.postMessage(message);
 13	}
 14	
 15	function formatPackageSummary(packages: DashboardData["packages"]): string {
 16		if (packages.configured === 0) return "No Pi packages configured.";
 17		const installed = `${packages.installed} installed`;
 18		const missing = packages.missing > 0 ? `, ${packages.missing} missing` : "";
 19		return `${packages.configured} configured · ${installed}${missing}`;
 20	}
 21	
 22	function ResourceToggle({
 23		resource,
 24	}: {
 25		resource: BundledResourceRow;
 26	}): JSX.Element {
 27		const description =
 28			resource.kind === "theme"
 29				? "A CodePi-only theme bundled with the extension."
 30				: "An extension bundled with CodePi for new sessions.";
 31	
 32		return (
 33			<label className="settings-resource-row">
 34				<span className="settings-resource-copy">
 35					<span className="settings-resource-label">{resource.label}</span>
 36					<span className="settings-help">{description}</span>
 37				</span>
 38				<input
 39					type="checkbox"
 40					checked={resource.enabled}
 41					onChange={(event) =>
 42						post({
 43							command: "settings:setBundledResource",
 44							id: resource.id,
 45							enabled: event.currentTarget.checked,
 46						})
 47					}
 48					aria-label={`Enable ${resource.label}`}
 49				/>
 50			</label>
 51		);
 52	}
 53	
 54	function FileButton({
 55		file,
 56		label,
 57		exists,
 58	}: {
 59		file: "settings" | "models" | "auth";
 60		label: string;
 61		exists: boolean;
 62	}): JSX.Element {
 63		return (
 64			<div className="settings-file-row">
 65				<div>
 66					<strong>{label}</strong>
 67					<span className="settings-help">
 68						{exists ? "File exists" : "Created when opened"}
 69					</span>
 70				</div>
 71				<button
 72					className="settings-button settings-button-secondary"
 73					type="button"
 74					onClick={() => post({ command: "settings:openFile", file })}
 75				>
 76					Open in VS Code
 77				</button>
 78			</div>
 79		);
 80	}
 81	
 82	export function SettingsApp(): JSX.Element {
 83		const [data, setData] = useState<DashboardData | null>(null);
 84		const [status, setStatus] = useState("");
 85		const [error, setError] = useState("");
 86	
 87		const reload = useCallback(() => {
 88			setError("");
 89			post({ command: "settings:refresh" });
 90		}, []);
 91	
 92		useEffect(() => {
 93			const onMessage = (event: MessageEvent<SettingsReply>) => {
 94				const message = event.data;
 95				switch (message.command) {
 96					case "settings:data":
 97						setData(message.data);
 98						setError("");
 99						break;
100					case "settings:saved":
101						setStatus(
102							`${message.resource} preference saved; applies to new sessions.`,
103						);
104						break;
105					case "settings:opened":
106						setStatus(`Opened ${message.file}.json in VS Code.`);
107						break;
108					case "settings:error":
109						setError(message.message);
110						break;
111				}
112			};
113			window.addEventListener("message", onMessage);
114			post({ command: "settings:get" });
115			return () => window.removeEventListener("message", onMessage);
116		}, []);
117	
118		if (!data) {
119			if (error) {
120				return (
121					<div className="settings-page settings-loading">
122						<div className="settings-alert settings-alert-error" role="alert">
123							{error}
124						</div>
125						<button
126							className="settings-button settings-button-secondary"
127							type="button"
128							onClick={reload}
129						>
130							Retry
131						</button>
132					</div>
133				);
134			}
135			return (
136				<div className="settings-page settings-loading" role="status">
137					Loading CodePi settings…
138				</div>
139			);
140		}
141	
142		return (
143			<div className="settings-page">
144				<header className="settings-header">
145					<div>
146						<h1>CodePi settings</h1>
147						<p className="settings-help">
148							Pi resources are shared with the Pi CLI on this computer; CodePi
149							sessions remain computer-specific.
150						</p>
151					</div>
152					<button
153						className="settings-button settings-button-secondary"
154						type="button"
155						onClick={() => post({ command: "settings:openSessions" })}
156					>
157						Sessions
158					</button>
159				</header>
160	
161				{error && (
162					<div className="settings-alert settings-alert-error" role="alert">
163						{error}
164					</div>
165				)}
166				{status && (
167					<div className="settings-alert settings-alert-status" role="status">
168						{status}
169					</div>
170				)}
171	
172				<section className="settings-card" aria-labelledby="resources-title">
173					<div className="settings-card-heading">
174						<div>
175							<h2 id="resources-title">Pi resources</h2>
176							<p className="settings-help">
177								The canonical resource directory for this computer.
178							</p>
179						</div>
180						<button
181							className="settings-button settings-button-secondary"
182							type="button"
183							onClick={reload}
184						>
185							Refresh
186						</button>
187					</div>
188					<code className="settings-path">{data.agentDir}</code>
189					<p className="settings-summary">
190						{formatPackageSummary(data.packages)}
191					</p>
192					{data.packages.missing > 0 && (
193						<div className="settings-package-list">
194							{data.packages.entries
195								.filter((entry) => !entry.installed)
196								.map((entry) => (
197									<div
198										className="settings-package-missing"
199										key={`${entry.scope}:${entry.source}`}
200									>
201										<span>{entry.source}</span>
202										<span>{entry.scope} package missing</span>
203									</div>
204								))}
205						</div>
206					)}
207					<p className="settings-help">
208						CodePi sessions are stored separately at{" "}
209						<code>{data.sessionDir}</code>.
210					</p>
211				</section>
212	
213				<section className="settings-card" aria-labelledby="defaults-title">
214					<h2 id="defaults-title">CodePi defaults</h2>
215					<p className="settings-help">
216						These resources ship with CodePi and are not installed into the Pi
217						CLI. Changes apply to new sessions.
218					</p>
219					<div className="settings-resource-list">
220						{data.bundledResources.map((resource) => (
221							<ResourceToggle key={resource.id} resource={resource} />
222						))}
223					</div>
224				</section>
225	
226				<section className="settings-card" aria-labelledby="files-title">
227					<h2 id="files-title">Pi files</h2>
228					<p className="settings-help">
229						Edit the real Pi files with VS Code’s JSON language service and
230						diagnostics.
231					</p>
232					<div className="settings-file-list">
233						<FileButton
234							file="settings"
235							label="settings.json"
236							exists={data.files.settings.exists}
237						/>
238						<FileButton
239							file="models"
240							label="models.json"
 45			this.sessionDir = sessionDir ?? getCodePiSessionDir(agentDir);
 46		}
 47	
 48		resolveWebviewView(webviewView: vscode.WebviewView): void {
 49			this.view = webviewView;
 50			webviewView.webview.options = {
 51				enableScripts: true,
 52				localResourceRoots: [
 53					vscode.Uri.joinPath(this.extensionUri, "webview-ui", "dist"),
 54				],
 55			};
 56			webviewView.webview.html = buildSettingsHtml(
 57				this.extensionUri,
 58				webviewView.webview,
 59			);
 60			webviewView.webview.onDidReceiveMessage((msg: SettingsMessage) => {
 61				void this.handleMessage(msg);
 62			});
 63		}
 64	
 65		private async handleMessage(msg: SettingsMessage): Promise<void> {
 66			try {
 67				switch (msg.command) {
 68					case "settings:get":
 69					case "settings:refresh":
 70						if (msg.command === "settings:refresh") this.onConfigSaved();
 71						await this.sendData();
 72						break;
 73					case "settings:setBundledResource":
 74						await this.setBundledResource(msg.id, msg.enabled);
 75						break;
 76					case "settings:openFile":
 77						await this.openFile(msg.file);
 78						break;
 79					case "settings:openSessions":
 80						await vscode.commands.executeCommand("codepi.openSessionsTab");
 81						break;
 82				}
 83			} catch (err) {
 84				this.post({
 85					command: "settings:error",
 86					message: err instanceof Error ? err.message : String(err),
 87				});
 88			}
 89		}
 90	
 91		private post(msg: SettingsReply): void {
 92			this.view?.webview.postMessage(msg);
 93		}
 94	
 95		private async sendData(): Promise<void> {
 96			const settingsPath = getSettingsPathForAgent(this.agentDir);
 97			const settings = readJsonFile<Record<string, unknown>>(settingsPath) ?? {};
 98			const sdk = await getSdk();
 99			const cwd =
100				vscode.workspace.workspaceFolders?.[0]?.uri.fsPath ?? this.agentDir;
101			const settingsManager = sdk.SettingsManager.create(cwd, this.agentDir);
102			const packageManager = new sdk.DefaultPackageManager({
103				cwd,
104				agentDir: this.agentDir,
105				settingsManager,
106			});
107			const packages: PackageStatusEntry[] = packageManager
108				.listConfiguredPackages()
109				.map((entry) => ({
110					source: entry.source,
111					scope: entry.scope,
112					installed: entry.installedPath !== undefined,
113				}));
114			const data = buildDashboardData(
115				this.agentDir,
116				this.sessionDir,
117				settings,
118				packages,
119				getDashboardFileStatus(this.agentDir),
120			);
121			this.post({ command: "settings:data", data });
122		}
123	
124		private async setBundledResource(
125			id: DashboardData["bundledResources"][number]["id"],
126			enabled: boolean,
127		): Promise<void> {
128			const settingsPath = getSettingsPathForAgent(this.agentDir);
129			if (!isBundledResourceId(id)) {
130				throw new Error(`Unknown bundled resource: ${id}`);
131			}
